class _MyHomePageState extends State<MyHomePage>{
  late VideoPlayerController videoPlayerController;
  late CustomVideoPlayerController _customVideoPlayerController;
  @override
  void initState(){
    super.initState();
    videoPlayerController=VideoPlayerController.network('https://example.com/video.mp4')..initialize().then((_)=>setState((){}));
    _customVideoPlayerController=CustomVideoPlayerController(context:context,videoPlayerController:videoPlayerController);
  }
  @override
  void dispose(){
    _customVideoPlayerController.dispose();
    super.dispose();
  }
  @override
  Widget build(BuildContext context){
    return CustomVideoPlayer(customVideoPlayerController:_customVideoPlayerController);
  }
}
